# Check if the ffmpeg command can be executed safely
import subprocess

def test_ffmpeg_command():
    try:
        command = ['ffmpeg', '-version']
        result = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        print("FFmpeg is available:", result.stdout.decode())
    except subprocess.CalledProcessError as e:
        print("Error executing FFmpeg command:", e.stderr.decode())

test_ffmpeg_command()
